const FONT = 'Times New Roman'
const MONO = 'Courier New'
const LINE = 360 // 1,5 интервала
const INDENT = 709 // 1,25 см
const PT24 = 480

const fx = (v, d = 2) => (v == null ? '—' : v.toFixed(d).replace('.', ','))
const x = v => (v == null ? '—' : `${fx(v)}x`)
const pct = v => (v == null ? '—' : `${fx(v, 1)} %`)
const n0 = v => Math.round(v).toLocaleString('ru-RU').replace(/ /g, ' ')

