// ------------------------------------------------------------------ примитивы
const run = (t, o = {}) => new TextRun({ text: t, font: o.mono ? MONO : FONT, size: o.size ?? 28 })
function p(text, o = {}) {
  const runs = Array.isArray(text) ? text : [run(text, o)]
  return new Paragraph({
    children: runs, alignment: o.align ?? AlignmentType.JUSTIFIED,
    indent: o.noIndent ? undefined : { firstLine: o.firstLine ?? INDENT },
    spacing: { line: o.line ?? LINE, before: o.before ?? 0, after: o.after ?? 0 },
    keepNext: o.keepNext, pageBreakBefore: o.pageBreak,
  })
}
const center = (t, o = {}) => p(t, { ...o, align: AlignmentType.CENTER, noIndent: true })

function structural(t, { toc = true } = {}) { // СОДЕРЖАНИЕ, ВВЕДЕНИЕ, ЗАКЛЮЧЕНИЕ ...
  return new Paragraph({
    children: [run(t)], heading: toc ? HeadingLevel.HEADING_1 : undefined, alignment: AlignmentType.CENTER,
    pageBreakBefore: true, keepNext: true, spacing: { line: LINE, before: 0, after: PT24 },
  })
}
function h1(t) {
  return new Paragraph({
    children: [run(t)], heading: HeadingLevel.HEADING_1, alignment: AlignmentType.LEFT, indent: { firstLine: INDENT },
    pageBreakBefore: true, keepNext: true, keepLines: true, spacing: { line: LINE, before: 0, after: PT24 },
  })
}
function h2(t) {
  return new Paragraph({
    children: [run(t)], heading: HeadingLevel.HEADING_2, alignment: AlignmentType.LEFT, indent: { firstLine: INDENT },
    keepNext: true, keepLines: true, spacing: { line: LINE, before: PT24, after: PT24 },
  })
}
const dash = t => new Paragraph({
  children: [run(t)], numbering: { reference: 'dash', level: 0 }, alignment: AlignmentType.JUSTIFIED,
  spacing: { line: LINE },
})
let numInst = 0
function numbered(items) {
  numInst += 1
  return items.map(t => new Paragraph({
    children: [run(t)], numbering: { reference: 'num', level: 0, instance: numInst }, alignment: AlignmentType.JUSTIFIED,
    spacing: { line: LINE },
  }))
}

function pngSize(file) {
  const b = fs.readFileSync(file)
  return { w: b.readUInt32BE(16), h: b.readUInt32BE(20), data: b }
}
function figure(file, caption, widthCm = 16, label = null, pageBreak = false) {
  const { w, h, data } = pngSize(path.join(HERE, 'figures', file))
  const pxW = widthCm / 2.54 * 96
  const num = label ?? `${++figN}`
  figAll += 1
  return [
    new Paragraph({ pageBreakBefore: pageBreak, children: [new ImageRun({ type: 'png', data, transformation: { width: pxW, height: pxW * h / w } })],
      alignment: AlignmentType.CENTER, keepNext: true, spacing: { before: 120, after: 120 } }),
    center(`Рисунок ${num} – ${caption}`, { after: 240 }),
  ]
}

const border = { style: BorderStyle.SINGLE, size: 4, color: '000000' }
const borders = { top: border, bottom: border, left: border, right: border }
function cell(t, width, o = {}) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA }, borders, verticalAlign: VerticalAlign.CENTER,
    margins: { top: 40, bottom: 40, left: 80, right: 80 },
    children: [new Paragraph({ children: [run(String(t), { size: 24 })], alignment: o.align ?? AlignmentType.LEFT,
      spacing: { line: 240 }, keepNext: o.keepNext })],
  })
}
function table(caption, headers, rows, widths, { label = null, alignNum = [] } = {}) {
  const num = label ?? `${++tabN}`
  tabAll += 1
  const total = widths.reduce((a, b) => a + b, 0)
  const al = i => (alignNum.includes(i) ? AlignmentType.CENTER : AlignmentType.LEFT)
  return [
    p(`Таблица ${num} – ${caption}`, { noIndent: true, align: AlignmentType.LEFT, keepNext: true, before: 120 }),
    new Table({
      width: { size: total, type: WidthType.DXA }, columnWidths: widths, layout: TableLayoutType.FIXED,
      rows: [
        new TableRow({ tableHeader: true, height: { value: 454, rule: 'atLeast' },
          children: headers.map((h, i) => cell(h, widths[i], { align: AlignmentType.CENTER, keepNext: true })) }),
        // небольшие таблицы не разрываются между страницами (иначе нужна строка «Продолжение таблицы»)
        ...rows.map((r, ri) => new TableRow({ height: { value: 454, rule: 'atLeast' }, cantSplit: true,
          children: r.map((c, i) => cell(c, widths[i], { align: al(i), keepNext: rows.length <= 20 && ri < rows.length - 1 })) })),
      ],
    }),
    p('', { noIndent: true, line: 240 }),
  ]
}
function listing(caption, code, label = null) {
  const num = label ?? `${++lstN}`
  return [
    p(`Листинг ${num} – ${caption}`, { noIndent: true, align: AlignmentType.LEFT, keepNext: true, before: 120 }),
    ...code.split('\n').map((l, i, arr) => new Paragraph({
      children: [run(l.length ? l : ' ', { mono: true, size: 24 })], keepNext: i < arr.length - 1,
      spacing: { line: 240 }, indent: { left: 0 },
    })),
    p('', { noIndent: true, line: 240 }),
  ]
}

