function appendixHead(letter, kind, title) {
  return [
    new Paragraph({ children: [run(`ПРИЛОЖЕНИЕ ${letter}`)], heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER,
      pageBreakBefore: true, keepNext: true, spacing: { line: LINE } }),
    center(`(${kind})`, { keepNext: true }),
    center(title, { keepNext: true, after: PT24 }),
  ]
}

